//! # Textos de la interfaz (`textos.rs`)
//!
//! Todo lo que la aplicación le dice al usuario vive aquí, y no repartido por el código que
//! dibuja la pantalla.
//!
//! ## Por qué
//!
//! Por dos razones, y la segunda no es la evidente.
//!
//! 1. **Para poder hablar otros idiomas.** Con los textos centralizados, añadir uno es
//!    escribir una columna más; con los textos incrustados en cada botón, es recorrer el
//!    programa entero.
//!
//! 2. **Para que renombrar código no toque lo que lee el usuario.** Esta es la que costó
//!    caro. Un renombrado masivo de identificadores al español alcanzó a `content` —la clave
//!    con la que el protocolo MCP devuelve el resultado de una llamada— porque estaba escrita
//!    dentro de una cadena, igual que los rótulos de los botones. El servidor quedó
//!    inservible y las pruebas siguieron en verde, porque el mismo cambio volteó también sus
//!    literales.
//!
//! ## Por qué hay seis funciones de quinientas líneas, y por qué se quedan así
//!
//! Las funciones [`Texto::espanol`], [`Texto::ingles`] y las otras cuatro miden entre 526 y
//! 577 líneas, muy por encima del límite que fija el estándar 2 de `CLAUDE.md`. Es
//! deliberado, y estas son las razones, medidas el 2026-09-06.
//!
//! **No son lógica: son una tabla.** Un `match` de mapeo puro no tiene ninguna decisión
//! dentro; su complejidad ciclomática real es 1. Lo que crece con el tamaño no es la
//! dificultad de entenderlo, sino el número de textos de la aplicación, que hoy son 493 en
//! seis idiomas. Partirlo en trozos no lo haría más fácil de seguir: haría falta buscar en
//! qué trozo cayó cada texto.
//!
//! **La forma actual la vigila el compilador.** Al añadir una variante a [`Texto`] sin
//! traducirla, `cargo build` falla con **seis errores** `E0004`, uno por idioma, diciendo
//! exactamente cuál falta. Comprobado introduciendo una variante de prueba: seis errores,
//! ninguno evitable.
//!
//! **La alternativa perdería esa garantía.** Trocear cada idioma en funciones más pequeñas
//! obliga a que devuelvan `Option<&str>` y se encadenen, y en cuanto hay un `_ =>` o un
//! `None` de reserva, el compilador deja de exigir nada: un texto sin traducir compilaría, y
//! el fallo aparecería en la pantalla de un usuario que hable ese idioma. Se cambiaría una
//! garantía de compilación por una de prueba, que es un grado menos.
//!
//! Cuando cumplir la letra de una norma empeora lo que la norma protege, se anota y se deja
//! como está. Lo mismo vale para [`crate::ui::ayuda_textos`], por el mismo motivo.
//!
//!    Mientras el texto de la interfaz y las claves de un protocolo convivan como cadenas
//!    sueltas en los mismos archivos, cualquier búsqueda y reemplazo puede confundirlos. Aquí
//!    están separados: en este módulo hay **solo** cosas que lee una persona, y lo que hay
//!    fuera no se traduce nunca.
//!
//! ## Cómo se usa
//!
//! ```ignore
//! ui.button(Texto::MenuArchivoNuevo.en(app.idioma));
//! ```
//!
//! La traducción de cada clave es un `match` exhaustivo por idioma. Añadir un idioma no
//! compila hasta que **todas** las claves lo tienen, y añadir una clave no compila hasta que
//! la tienen todos los idiomas: no se puede olvidar ninguna traducción a medias.
//!
//! ## Qué NO va aquí
//!
//! - Las claves de los protocolos y de los archivos (`content`, `root_node`, `file_path`…).
//!   No las lee una persona: son contrato, y traducirlas rompe la compatibilidad.
//! - Los nombres canónicos con los que las enumeraciones se guardan en disco.
//! - Las guías de la ayuda, que son documentos largos y viven en su propio módulo.

use crate::error::{
    CampoEntrada, ClaveError, FalloEsquemaMarkdown, FalloEstructural, FalloJsonIa,
    MotivoCarpetaInvalida, MotivoEntradaInvalida,
};
use serde::{Deserialize, Serialize};

/// Idiomas en los que la aplicación sabe hablar.
///
/// Se guarda en las preferencias, así que los **nombres de las variantes** son contrato del
/// archivo `preferencias.json` y no se traducen ni se cambian.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, Serialize, Deserialize)]
pub enum Idioma {
    /// Castellano. Es el idioma en que se escribió el programa.
    #[default]
    Espanol,
    /// Inglés.
    Ingles,
    /// Francés.
    Frances,
    /// Alemán.
    Aleman,
    /// Ruso.
    Ruso,
    /// Chino simplificado.
    ChinoSimplificado,
}

impl Idioma {
    /// Todos los idiomas, en el orden en que se ofrecen en el menú.
    ///
    /// El castellano y el inglés van primero por ser los dos con los que nació el programa;
    /// el resto, en el orden en que se tradujeron.
    pub const TODOS: [Idioma; 6] = [
        Idioma::Espanol,
        Idioma::Ingles,
        Idioma::Frances,
        Idioma::Aleman,
        Idioma::Ruso,
        Idioma::ChinoSimplificado,
    ];

    /// Cómo se llama el idioma **en ese mismo idioma**.
    ///
    /// Es lo que espera quien va a elegirlo: alguien que busca el inglés reconoce «English»
    /// aunque no entienda el resto de la pantalla.
    pub fn nombre_para_interfaz(self) -> &'static str {
        match self {
            Idioma::Espanol => "Español",
            Idioma::Ingles => "English",
            Idioma::Frances => "Français",
            Idioma::Aleman => "Deutsch",
            Idioma::Ruso => "Русский",
            Idioma::ChinoSimplificado => "简体中文",
        }
    }

    /// Bandera con la que se acompaña al nombre en el menú.
    pub fn bandera(self) -> &'static str {
        match self {
            Idioma::Espanol => "🇪🇸",
            Idioma::Ingles => "🇬🇧",
            Idioma::Frances => "🇫🇷",
            Idioma::Aleman => "🇩🇪",
            Idioma::Ruso => "🇷🇺",
            Idioma::ChinoSimplificado => "🇨🇳",
        }
    }

    /// Traduce al idioma de la interfaz la etiqueta que declara el sistema operativo.
    ///
    /// Acepta las dos notaciones que llegan en la práctica, porque cada sistema usa la suya:
    ///
    /// - **BCP 47**, la de Windows y macOS: `es-ES`, `zh-Hans-CN`.
    /// - **POSIX**, la de las variables `LANG` y `LC_*`: `es_ES.UTF-8`, `de_AT@euro`.
    ///
    /// Se compara el **subtag primario entero**, nunca un prefijo: `et` (estonio) empieza
    /// por `e` igual que `es`, y confundirlos abriría el programa en un idioma ajeno.
    ///
    /// # Parámetros
    /// - `etiqueta`: lo que declara el sistema, tal cual, con codificación y modificador
    ///   si los trae.
    ///
    /// # Devuelve
    /// El idioma correspondiente, o `None` si no es ninguno de los seis. Qué hacer entonces
    /// lo decide quien llama: aquí no se elige un sustituto por cuenta propia.
    pub fn desde_etiqueta_del_sistema(etiqueta: &str) -> Option<Idioma> {
        // Ni la codificación ni el modificador dicen nada del idioma: en `es_ES.UTF-8@euro`
        // sobra todo lo que va del primer punto o arroba en adelante.
        let sin_adornos = etiqueta.split(['.', '@']).next().unwrap_or_default();
        let normalizada = sin_adornos.replace('_', "-").to_lowercase();

        let mut partes = normalizada.split('-');
        let primario = partes.next().unwrap_or_default();
        let resto: Vec<&str> = partes.collect();

        match primario {
            "es" => Some(Idioma::Espanol),
            "en" => Some(Idioma::Ingles),
            "fr" => Some(Idioma::Frances),
            "de" => Some(Idioma::Aleman),
            "ru" => Some(Idioma::Ruso),
            // El programa solo habla chino simplificado. A quien tenga el sistema en
            // tradicional se le responde que no: mostrarle simplificado no sería traducirle,
            // sería darle un texto que no es el suyo fingiendo que sí lo es.
            "zh" => {
                let es_tradicional = resto
                    .iter()
                    .any(|subtag| matches!(*subtag, "hant" | "tw" | "hk" | "mo"));
                (!es_tradicional).then_some(Idioma::ChinoSimplificado)
            }
            _ => None,
        }
    }

    /// El idioma en el que está configurado el sistema, si el programa lo habla.
    ///
    /// Se usa **solo en el primer arranque**, cuando todavía no hay preferencias guardadas.
    /// A partir de ahí manda lo que el usuario haya elegido en el menú.
    ///
    /// # Devuelve
    /// El idioma del sistema, o el castellano si el sistema no lo dice o si es uno de los
    /// que el programa no habla. El castellano es el idioma en que se escribió MMCelt y
    /// sigue siendo el respaldo.
    pub fn del_sistema() -> Idioma {
        etiqueta_del_sistema()
            .as_deref()
            .and_then(Idioma::desde_etiqueta_del_sistema)
            .unwrap_or(Idioma::Espanol)
    }
}

/// Pregunta al sistema operativo en qué idioma está configurado.
///
/// Windows no publica el idioma en ninguna variable de entorno, así que hay que
/// preguntárselo: `GetUserDefaultLocaleName` devuelve la etiqueta BCP 47 del usuario
/// —«es-ES»—, que es la misma que muestra la configuración regional.
///
/// # Devuelve
/// La etiqueta, o `None` si el sistema no la facilita.
#[cfg(windows)]
pub(crate) fn etiqueta_del_sistema() -> Option<String> {
    /// Tamaño máximo de una etiqueta de configuración regional, contando el terminador
    /// nulo. Lo fija la propia API de Windows en `LOCALE_NAME_MAX_LENGTH`.
    const LONGITUD_MAXIMA: usize = 85;

    #[link(name = "kernel32")]
    extern "system" {
        /// Devuelve la configuración regional del usuario, como `es-ES` o `zh-CN`.
        ///
        /// Es la función de `kernel32` de Windows, declarada aquí en vez de arrastrar una
        /// dependencia entera solo para leer un idioma.
        ///
        /// # Parámetros
        /// - `lp_locale_name`: búfer donde escribe el nombre, en UTF-16.
        /// - `cch_locale_name`: capacidad real de ese búfer, en caracteres.
        ///
        /// # Devuelve
        /// Cuántos caracteres ha escrito, contando el terminador nulo, o `0` si falla.
        fn GetUserDefaultLocaleName(lp_locale_name: *mut u16, cch_locale_name: i32) -> i32;
    }

    let mut destino = [0u16; LONGITUD_MAXIMA];

    // SEGURIDAD: se le pasa la capacidad real del búfer, así que la función no puede
    // escribir más allá de él. Devuelve cuántos caracteres escribió contando el terminador
    // nulo, o 0 si falla; después solo se lee lo que ella misma declara haber escrito.
    let escritos =
        unsafe { GetUserDefaultLocaleName(destino.as_mut_ptr(), LONGITUD_MAXIMA as i32) };

    // Un solo carácter es la cadena vacía con su terminador: no dice nada.
    if escritos <= 1 {
        return None;
    }

    let sin_terminador = &destino[..(escritos as usize - 1)];
    Some(String::from_utf16_lossy(sin_terminador))
}

/// Pregunta al sistema operativo en qué idioma está configurado.
///
/// En Linux y macOS el idioma viaja en las variables POSIX. Se miran en su orden de
/// precedencia: `LC_ALL` manda sobre todas, `LC_MESSAGES` rige los textos del programa y
/// `LANG` es el valor general.
///
/// # Devuelve
/// La primera variable que traiga algo, o `None` si ninguna está definida.
#[cfg(not(windows))]
pub(crate) fn etiqueta_del_sistema() -> Option<String> {
    ["LC_ALL", "LC_MESSAGES", "LANG"]
        .iter()
        .find_map(|nombre| std::env::var(nombre).ok())
        .filter(|valor| !valor.is_empty())
}

