    /// Todas las claves, para poder recorrerlas en las comprobaciones.
    ///
    /// Existe **solo para las pruebas**: la aplicación nombra cada texto donde lo necesita,
    /// nunca los recorre todos.
    ///
    /// Lo que impide olvidarse de una clave es el `match` exhaustivo de la prueba que la
    /// recorre, no este array: aquí el compilador solo comprueba que la cuenta cuadre con el
    /// tamaño declarado. Decía que «añadir una variante y no añadirla aquí no compila», y eso
    /// no era cierto: una clave nueva que no llegara a esta lista se escapaba en silencio de
