impl ClaveError {
    /// Traduce la clave de error al idioma seleccionado.
    pub fn en(&self, idioma: Idioma) -> String {
        match self {
            ClaveError::Lectura { ruta, origen } => match idioma {
                Idioma::Espanol => format!("No se pudo leer «{}»: {origen}. Comprueba que el archivo existe y que tienes permiso para abrirlo.", ruta.display()),
                Idioma::Ingles => format!("Could not read «{}»: {origen}. Check that the file exists and you have permission to open it.", ruta.display()),
                Idioma::Frances => format!("Impossible de lire «{}» : {origen}. Vérifiez que le fichier existe et que vous avez la permission de l'ouvrir.", ruta.display()),
                Idioma::Aleman => format!("Konnte «{}» nicht lesen: {origen}. Prüfen Sie, ob die Datei existiert und Sie über die nötigen Leserechte verfügen.", ruta.display()),
                Idioma::Ruso => format!("Не удалось прочитать «{}»: {origen}. Убедитесь, что файл существует и у вас есть разрешение на его открытие.", ruta.display()),
                Idioma::ChinoSimplificado => format!("无法读取 «{}»：{origen}。请检查文件是否存在且您具有打开它的权限。", ruta.display()),
            },
            ClaveError::Escritura { ruta, origen } => match idioma {
                Idioma::Espanol => format!("No se pudo guardar en «{}»: {origen}. Comprueba que la carpeta existe y que tienes permiso de escritura.", ruta.display()),
                Idioma::Ingles => format!("Could not save to «{}»: {origen}. Check that the folder exists and you have write permission.", ruta.display()),
                Idioma::Frances => format!("Impossible d'enregistrer dans «{}» : {origen}. Vérifiez que le dossier existe et que vous avez la permission d'écriture.", ruta.display()),
                Idioma::Aleman => format!("Konnte nicht in «{}» speichern: {origen}. Prüfen Sie, ob der Ordner existiert und Sie über Schreibrechte verfügen.", ruta.display()),
                Idioma::Ruso => format!("Не удалось сохранить в «{}»: {origen}. Убедитесь, что папка существует и у вас есть права на запись.", ruta.display()),
                Idioma::ChinoSimplificado => format!("无法保存到 «{}»：{origen}。请检查文件夹是否存在且您具有写入权限。", ruta.display()),
            },
            ClaveError::Formato { contexto, origen } => match idioma {
                Idioma::Espanol => format!("El archivo no tiene el formato esperado ({contexto}): {origen}. Si lo ha generado una IA, revisa que los campos «status», «priority» y «role» usen los valores admitidos."),
                Idioma::Ingles => format!("The file does not have the expected format ({contexto}): {origen}. If generated by an AI, verify that «status», «priority» and «role» use accepted values."),
                Idioma::Frances => format!("Le fichier n'a pas le format attendu ({contexto}) : {origen}. S'il a été généré par une IA, vérifiez que «status», «priority» et «role» utilisent des valeurs admises."),
                Idioma::Aleman => format!("Die Datei hat nicht das erwartete Format ({contexto}): {origen}. Falls von einer KI erzeugt, prüfen Sie, ob «status», «priority» und «role» zulässige Werte nutzen."),
                Idioma::Ruso => format!("Файл имеет непредвиденный формат ({contexto}): {origen}. Если он создан ИИ, проверьте допустимость значений полей «status», «priority» и «role»."),
                Idioma::ChinoSimplificado => format!("文件格式不符合预期 ({contexto})：{origen}。如果是由 AI 生成的，请检查 «status»、«priority» 和 «role» 字段是否使用允许的值。"),
            },
            ClaveError::EstructuraInvalida(fallo) => {
                let desc = fallo.en(idioma);
                match idioma {
                    Idioma::Espanol => format!("El mapa mental está dañado y no se puede abrir: {desc}. Se ha impedido su carga para no bloquear la aplicación."),
                    Idioma::Ingles => format!("The mind map is corrupted and cannot be opened: {desc}. Loading was aborted to prevent application lockup."),
                    Idioma::Frances => format!("La carte mentale est endommagée et ne peut pas être ouverte : {desc}. Son chargement a été bloqué pour ne pas figer l'application."),
                    Idioma::Aleman => format!("Die Mindmap ist beschädigt und kann nicht geöffnet werden: {desc}. Das Laden wurde verhindert, um ein Blockieren der Anwendung zu vermeiden."),
                    Idioma::Ruso => format!("Интеллект-карта повреждена и не может быть открыта: {desc}. Загрузка предотвращена во избежание сбоя приложения."),
                    Idioma::ChinoSimplificado => format!("思维导图已损坏且无法打开：{desc}。已阻止其加载以防止应用程序被锁定。"),
                }
            }
            ClaveError::ImportacionIa { error_json, error_esquema } => {
                let err_j = error_json.en(idioma);
                let err_e = error_esquema.en(idioma);
                match idioma {
                    Idioma::Espanol => format!("No se pudo interpretar la respuesta de la IA.\n· Como JSON: {err_j}\n· Como esquema Markdown: {err_e}\nPide al modelo que genere únicamente el bloque JSON del prompt maestro."),
                    Idioma::Ingles => format!("Could not interpret AI response.\n· As JSON: {err_j}\n· As Markdown outline: {err_e}\nAsk the model to generate only the JSON block from the master prompt."),
                    Idioma::Frances => format!("Impossible d'interpréter la réponse de l'IA.\n· En tant que JSON : {err_j}\n· En tant que plan Markdown : {err_e}\nDemandez au modèle de générer uniquement le bloc JSON du prompt maître."),
                    Idioma::Aleman => format!("Die Antwort der KI konnte nicht interpretiert werden.\n· Als JSON: {err_j}\n· Als Markdown-Gliederung: {err_e}\nBitten Sie das Modell, nur den JSON-Block aus dem Master-Prompt zu erzeugen."),
                    Idioma::Ruso => format!("Не удалось интерпретировать ответ ИИ.\n· Как JSON: {err_j}\n· Как разметку Markdown: {err_e}\nПопросите модель сгенерировать только блок JSON из главного промпта."),
                    Idioma::ChinoSimplificado => format!("无法解析 AI 的回复。\n· 作为 JSON：{err_j}\n· 作为 Markdown 大纲：{err_e}\n请让模型仅生成主提示词中的 JSON 代码块。"),
                }
            }
            ClaveError::CarpetaInvalida { ruta, motivo } => {
                let mot = motivo.en(idioma);
                match idioma {
                    Idioma::Espanol => format!("La carpeta «{}» no puede usarse como proyecto: {mot}. Elige una carpeta concreta con permiso de lectura y escritura.", ruta.display()),
                    Idioma::Ingles => format!("The folder «{}» cannot be used as a project: {mot}. Choose a specific folder with read and write permissions.", ruta.display()),
                    Idioma::Frances => format!("Le dossier «{}» ne peut pas être utilisé comme projet : {mot}. Choisissez un dossier spécifique avec autorisations de lecture et écriture.", ruta.display()),
                    Idioma::Aleman => format!("Der Ordner «{}» kann nicht als Projekt genutzt werden: {mot}. Wählen Sie einen konkreten Ordner mit Lese- und Schreibzugriff.", ruta.display()),
                    Idioma::Ruso => format!("Папка «{}» не может использоваться в качестве проекта: {mot}. Выберите определённую папку с правами чтения и записи.", ruta.display()),
                    Idioma::ChinoSimplificado => format!("文件夹 «{}» 无法用作项目：{mot}。请选择具有读写权限的具体文件夹。", ruta.display()),
                }
            }
            ClaveError::IdentidadProyectoDistinta => match idioma {
                Idioma::Espanol => "La entrega pertenece a otro proyecto y no se aplicará al mapa activo.".to_string(),
                Idioma::Ingles => "The delivery belongs to another project and will not be applied to the active map.".to_string(),
                Idioma::Frances => "La livraison appartient à un autre projet et ne sera pas appliquée à la carte active.".to_string(),
                Idioma::Aleman => "Die Lieferung gehört zu einem anderen Projekt und wird nicht auf die aktive Map angewendet.".to_string(),
                Idioma::Ruso => "Результат принадлежит другому проекту и не будет применён к активной карте.".to_string(),
                Idioma::ChinoSimplificado => "交付内容属于另一个项目，不会应用到当前活动导图中。".to_string(),
            },
            ClaveError::RutaFueraDelProyecto => match idioma {
                Idioma::Espanol => "La operación se ha detenido porque la ruta sale de la carpeta del proyecto.".to_string(),
                Idioma::Ingles => "Operation halted because the path leaves the project folder.".to_string(),
                Idioma::Frances => "L'opération s'est arrêtée car le chemin sort du dossier du projet.".to_string(),
                Idioma::Aleman => "Vorgang abgebrochen, da der Pfad den Projektordner verlässt.".to_string(),
                Idioma::Ruso => "Операция остановлена, так как путь выходит за пределы папки проекта.".to_string(),
                Idioma::ChinoSimplificado => "操作已中止，因为路径超出了项目文件夹的范围。".to_string(),
            },
            ClaveError::EntradaDemasiadoGrande { origen, limite } => {
                let mib = limite / (1024 * 1024);
                match idioma {
                    Idioma::Espanol => format!("No se puede abrir «{origen}» porque supera el límite de seguridad de {mib} MiB. Reduce su tamaño y vuelve a intentarlo."),
                    Idioma::Ingles => format!("Cannot open «{origen}» because it exceeds safety limit of {mib} MiB. Reduce size and try again."),
                    Idioma::Frances => format!("Impossible d'ouvrir «{origen}» car la taille dépasse la limite de sécurité de {mib} Mio. Réduisez sa taille et réessayez."),
                    Idioma::Aleman => format!("Kann «{origen}» nicht öffnen, da Sicherheitslimit von {mib} MiB überschritten ist. Größe verringern und erneut versuchen."),
                    Idioma::Ruso => format!("Невозможно открыть «{origen}», так как размер превышает безопасный предел в {mib} МиБ. Уменьшите размер и повторите попытку."),
                    Idioma::ChinoSimplificado => format!("无法打开 «{origen}»，因为超过了 {mib} MiB 的安全限制。请减小其大小并重试。"),
                }
            }
            ClaveError::EntradaInvalida { campo, motivo } => {
                let cmp = campo.en(idioma);
                let mot = motivo.en(idioma);
                match idioma {
                    Idioma::Espanol => format!("El campo «{cmp}» no puede utilizarse: {mot}. Corrígelo y vuelve a intentarlo."),
                    Idioma::Ingles => format!("Field «{cmp}» cannot be used: {mot}. Correct it and try again."),
                    Idioma::Frances => format!("Le champ «{cmp}» ne peut pas être utilisé : {mot}. Corrigez-le et réessayez."),
                    Idioma::Aleman => format!("Feld «{cmp}» kann nicht verwendet werden: {mot}. Korrigieren und erneut versuchen."),
                    Idioma::Ruso => format!("Поле «{cmp}» не может использоваться: {mot}. Исправьте его и повторите попытку."),
                    Idioma::ChinoSimplificado => format!("无法使用字段 «{cmp}»：{mot}。请更正后重试。"),
                }
            }
            ClaveError::ConfirmacionCaducada => match idioma {
                Idioma::Espanol => "La vista previa ha caducado porque cambió el mapa o alguna instrucción. Revísala de nuevo antes de iniciar el agente.".to_string(),
                Idioma::Ingles => "Preview expired because the map or instructions changed. Review again before launching the agent.".to_string(),
                Idioma::Frances => "L'aperçu a expiré car la carte ou une instruction a changé. Révisez à nouveau avant de lancer l'agent.".to_string(),
                Idioma::Aleman => "Vorschau abgelaufen, da Map oder Anweisungen geändert wurden. Vor dem Start des Agenten erneut prüfen.".to_string(),
                Idioma::Ruso => "Предпросмотр устарел из-за изменений в карте или инструкциях. Проверьте заново перед запуском агента.".to_string(),
                Idioma::ChinoSimplificado => "预览已过期，因为导图或指令已更改。在启动代理前请重新检查。".to_string(),
            },
            ClaveError::Vigilancia { ruta, origen } => match idioma {
                Idioma::Espanol => format!("No se pudo vigilar «{}»: {origen}. Comprueba que la carpeta exista y siga disponible.", ruta.display()),
                Idioma::Ingles => format!("Could not watch «{}»: {origen}. Check that the folder exists and remains accessible.", ruta.display()),
                Idioma::Frances => format!("Impossible de surveiller «{}» : {origen}. Vérifiez que le dossier existe et reste disponible.", ruta.display()),
                Idioma::Aleman => format!("Konnte «{}» nicht überwachen: {origen}. Prüfen Sie, ob der Ordner existiert und verfügbar bleibt.", ruta.display()),
                Idioma::Ruso => format!("Не удалось отслеживать «{}»: {origen}. Убедитесь, что папка существует и остаётся доступной.", ruta.display()),
                Idioma::ChinoSimplificado => format!("无法监视 «{}»：{origen}。请检查文件夹是否存在且可用。", ruta.display()),
            },
        }
    }
}
